import React, { useState } from "react";

export function MediaDropZone({ onSelectFile }: { onSelectFile: (file: File) => void }) {
  const [dragging, setDragging] = useState(false);

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) onSelectFile(file);
  };

  return (
    <div
      onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
      onDragLeave={() => setDragging(false)}
      onDrop={handleDrop}
      className={dragging ? "border-cyan-500 ring-2 ring-cyan-500/30 p-4 rounded-xl" : "border-slate-700 p-4 rounded-xl"}
    >
      Drop image or MP4 video here
    </div>
  );
}

